type IncludedItem={productId:number;quantity:number};
type Product = { id: number; name: string; price: number; memberPrice?:number|null; includedItems?:IncludedItem[]; isOffer?:boolean; icon: string; category: string; color: string };
type Discount={id:string;name:string;percent:number;active:boolean};
type Cart = Record<number, number>;
type Member = { id: string; name: string; role: string; code?: string; initials: string;active?:boolean;hasAccess?:boolean|number;whatsappNumber?:string|null;whatsappOptIn?:boolean|number;invoiceEmail?:string|null;invoiceEmailOptIn?:boolean|number;lifecycleStatus?:string;leftAt?:string|null;privacyReviewAt?:string|null };
