type UndoSale={id:string;undoToken:string;total:number;member:string;roundId?:string};
type RewardWin={campaignId:string;campaignName:string;rewardType:"free_item"|"percent";amount:number;label:string;originalTotal:number;total:number};
type SaleResult={total:number;originalTotal?:number;reward?:Omit<RewardWin,"originalTotal"|"total">|null;changeDue?:number;offline?:boolean};
type Allocation = { memberId: string; memberName: string; amount: number; kind: "anteil" | "runde" };
type RoundSpec = { id:string; sponsorId:string; sponsorName:string; label:string; totalUnits:number; maxPerMember:number };
type OpenRound = RoundSpec & { remaining:number; active:boolean; createdAt:string };
type GuestAccount={id:string;name:string;type:"visitor"|"club";parentId?:string|null;parentName?:string;visitDate?:string|null;active?:boolean};
type EventSummary={id:string;name:string;startsAt:string;endsAt?:string|null;status:"active"|"closed";notes?:string|null;productIds?:number[]|null;createdBy?:string;salesCount?:number;itemsCount?:number;revenue?:number};
type Profile={id:string;name:string;shortName:string;color:string;mustChangePin?:boolean;recoveryReady?:boolean};
type RecoveryCard={slot:number;code:string};
type InstallPromptEvent=Event&{prompt:()=>Promise<void>;userChoice:Promise<{outcome:"accepted"|"dismissed"}>};
type SplitAllocation={saleId:string;time:string;total:number;itemsLabel:string;memberId:string;memberName:string;amount:number;reversalId?:string|null};
