const money = (n: number) => n.toLocaleString("de-DE", { style: "currency", currency: "EUR" });
const invoiceWording=(value:string)=>value.replace(new RegExp(["Ze","chen"].join(""),"gi"),"Rechnungen").replace(new RegExp(["Ze","che"].join(""),"gi"),"Rechnung");
const currentBillingMonth=()=>{const parts=new Intl.DateTimeFormat("de-DE",{timeZone:"Europe/Berlin",year:"numeric",month:"2-digit"}).formatToParts(new Date());return `${parts.find(part=>part.type==="year")?.value}-${parts.find(part=>part.type==="month")?.value}`};
const memberRoles=(member:Pick<Member,"role">)=>member.role.split("+").filter(Boolean);
const memberHasRole=(member:Pick<Member,"role">,role:string)=>memberRoles(member).includes(role);
const hasProtectedAccess=(member:Pick<Member,"role">)=>["Vorstand","Kassenwart","Systemadmin"].some(role=>memberHasRole(member,role));
const memberRoleLabel=(member:Pick<Member,"role">)=>["Vorstand","Kassenwart","Systemadmin"].every(role=>memberHasRole(member,role))?"Hauptadministrator":memberRoles(member).map(role=>role==="Systemadmin"?"Systemadministration":role).join(" + ");
const paymentMethodLabel=(method?:string)=>method==="Vertrauensliste"?"Monatsabrechnung":method||"";
type AccountUrgency="guest"|"overdue"|"member";
const accountIds=(account:AccountSummary)=>new Set([account.memberId,...(account.children||[]).map(child=>child.memberId)]);
const flattenAccounts=(accounts:AccountSummary[])=>accounts.flatMap(account=>[account,...(account.children||[])]);
const accountOpenSince=(account:ControlData["accounts"][number],entries:NonNullable<ControlData["accountEntries"]>)=>{let reverseBalance=0;const current=Number(account.balance),ids=accountIds(account);for(const entry of entries.filter(item=>ids.has(item.memberId)).sort((a,b)=>b.createdAt.localeCompare(a.createdAt))){reverseBalance+=Number(entry.amount);if(reverseBalance>=current-.005)return entry.createdAt}return null};
const memberDueDate=(bookingDate:string)=>{const booking=new Date(bookingDate);return new Date(booking.getFullYear(),booking.getMonth()+1,10,23,59,59,999)};
const accountUrgency=(account:ControlData["accounts"][number],entries:NonNullable<ControlData["accountEntries"]>):AccountUrgency=>{if(account.accountType==="guest")return "guest";const since=accountOpenSince(account,entries);return since&&Date.now()>memberDueDate(since).getTime()?"overdue":"member"};
const accountStatusLabel=(account:ControlData["accounts"][number],entries:NonNullable<ControlData["accountEntries"]>)=>{const urgency=accountUrgency(account,entries);if(account.isClubGroup)return `⚠ Gastverein · ${(account.children||[]).length} offene Einzelkonten · bitte zeitnah abrechnen`;if(urgency==="guest")return account.parentName?`Gast bei ${account.parentName} · zählt zur Vereinsrechnung`:"⚠ Nichtmitglied · bitte zeitnah abrechnen";const since=accountOpenSince(account,entries);if(!since)return "Mitglied · Abrechnung zum Monatsende · zahlbar bis 10. des Folgemonats";const due=memberDueDate(since),date=due.toLocaleDateString("de-DE",{day:"2-digit",month:"2-digit",year:"numeric"});return urgency==="overdue"?`⚠ Mitglied · seit ${date} überfällig`:`Mitglied · Abrechnung zum Monatsende · zahlbar bis ${date}`};
const cleanMoneyInput=(value:string)=>{const parts=value.replace(".",",").replace(/[^\d,]/g,"").split(",");return parts.length>1?`${parts[0]},${parts.slice(1).join("").slice(0,2)}`:parts[0]};
const includedDescription=(product:Product,all:Product[])=>(product.includedItems||[]).map(item=>`${item.quantity}× ${all.find(candidate=>candidate.id===item.productId)?.name||"Artikel"}`).join(" + ");
const includedValue=(product:Product,all:Product[])=>(product.includedItems||[]).reduce((sum,item)=>sum+(all.find(candidate=>candidate.id===item.productId)?.price||0)*item.quantity,0);
const MembersContext=createContext<Member[]>(members);
const safeArray=<T,>(value:string|null):T[]=>{try{const parsed=JSON.parse(value||"[]");return Array.isArray(parsed)?parsed:[]}catch{return []}};

function ClubiqSignature({className=""}:{className?:string}){
  return <div className={`clubiq-signature ${className}`} role="img" aria-label={`${APP_NAME} – ${APP_SLOGAN}`}>
    <Image src="/brand/clubiq-ledger-symbol-gold.svg" alt="" width={22} height={22} unoptimized/>
    <div><strong>{APP_NAME}</strong><small>{APP_SLOGAN}</small></div>
  </div>;
}

