  const protectedAccess=roles.some(role=>role!=="Mitglied");
  return <div className="modal-backdrop" role="dialog" aria-modal="true" aria-labelledby="member-create-title"><form className="identity-card member-create-dialog member-create-simple" onSubmit={submit}><button type="button" className="modal-close" aria-label="Fenster schließen" onClick={onClose}>×</button><p className="eyebrow">NEUES MITGLIED</p><h2 id="member-create-title">Wer kommt dazu?</h2><p className="identity-sub">Für ein normales Mitglied reichen Vor- und Nachname. Alles Weitere ist freiwillig.</p><div className="member-name-fields"><label>Vorname<input autoFocus autoComplete="given-name" value={firstName} onChange={event=>setFirstName(event.target.value)} placeholder="z. B. Tom"/></label><label>Nachname<input autoComplete="family-name" value={lastName} onChange={event=>setLastName(event.target.value)} onKeyDown={event=>{if(event.key==="Enter"&&!showExtras)submit(event)}} placeholder="z. B. Taylor"/></label></div><div className="member-quick-summary"><span>✓</span><div><strong>Wird als Mitglied angelegt</strong><small>Kein Passwort nötig · RFID kann später zugeordnet werden</small></div></div><button type="button" className={`member-extra-toggle ${showExtras?"open":""}`} onClick={()=>setShowExtras(value=>!value)}><span>Funktion oder WhatsApp ergänzen</span><b>{showExtras?"−":"+"}</b></button>{showExtras&&<div className="member-extra-fields"><label>Funktion<select value={rolePreset} onChange={event=>setRolePreset(event.target.value)}><option value="Mitglied">Mitglied</option><option value="Kassenwart">Kassenwart</option><option value="Vorstand">Vorstand</option><option value="Systemadmin">Systemadministration</option><option value="Hauptadministrator">Hauptadministrator · alle Rechte</option><option value="Individuell">Mehrere Funktionen kombinieren …</option></select></label>{rolePreset==="Individuell"&&<fieldset className="member-role-choices compact"><legend>Funktionen kombinieren</legend>{[{id:"Kassenwart",label:"Kassenwart"},{id:"Vorstand",label:"Vorstand"},{id:"Systemadmin",label:"Systemadministration"}].map(option=><label key={option.id} className={customRoles.includes(option.id)?"selected":""}><input type="checkbox" checked={customRoles.includes(option.id)} onChange={()=>toggleRole(option.id)}/><span><strong>{option.label}</strong></span></label>)}</fieldset>}<label className={`whatsapp-consent ${whatsappOptIn?"selected":""}`}><input type="checkbox" checked={whatsappOptIn} onChange={event=>setWhatsappOptIn(event.target.checked)}/><span><strong>Für WhatsApp-Infos und Umfragen freigegeben</strong><small>Nur mit Zustimmung der Person aktivieren</small></span></label>{whatsappOptIn&&<label>WhatsApp-Nummer<input inputMode="tel" autoComplete="tel" value={whatsappNumber} onChange={event=>setWhatsappNumber(event.target.value.slice(0,30))} placeholder="+49 170 1234567"/><small className="field-help">{phoneValid?"Mit Ländervorwahl eingeben.":"Bitte eine vollständige Nummer mit +49 eingeben."}</small></label>}<div className={`role-access-note ${protectedAccess?"protected":""}`}><span>{protectedAccess?"🔒":"✓"}</span><div><strong>{protectedAccess?"Geschützter Zugang folgt im nächsten Schritt":"Kein Passwort nötig"}</strong><small>{protectedAccess?"Der persönliche Admin-Code wird nach dem Anlegen eingerichtet.":"Die Person kann sofort ausgewählt und bebucht werden."}</small></div></div></div>}{error&&<p className="profile-error" role="alert">{error}</p>}<button className="confirm-allocation" disabled={!valid||busy} type="submit">{busy?"Wird angelegt …":showExtras?"Mitglied mit Angaben anlegen":"Mitglied jetzt anlegen"}</button></form></div>;
