type InvoiceEmailData={configured:boolean;available:boolean;sender:string|null;replyTo:string|null;reason?:string;members:InvoiceEmailMember[]};
type MonthlyArchiveItem={month:string;label:string;dueDate:string;dueLabel:string;charges:number;people:number;salesCount:number;closed:boolean;statementNumber?:string|null;checksum?:string|null;closedByName?:string|null;closedAt?:string|null};
type BackupSnapshot={key:string;size:number;uploaded:string;checksum:string|null;schemaVersion:number;formatVersion:number;compatible:boolean;downloadUrl:string|null};
